// Bitrix manda POST form-urlencoded: event, data[FIELDS][ID], auth[application_token], ts.
// Dependendo da versao o n8n entrega achatado ("data[FIELDS][ID]") ou aninhado — cobrimos os dois.
const cfg = $('Config').first().json;
const raiz = $input.first().json;
const b = raiz.body ?? raiz;

const activityId =
  b['data[FIELDS][ID]'] ??
  b?.data?.FIELDS?.ID ??
  b?.FIELDS?.ID ??
  b?.activity_id ??
  b?.ID ??
  null;

// Seguranca: o Bitrix assina todo evento com o application_token do webhook de saida.
// Sem isto, qualquer um que descobrisse a URL do n8n moveria negocio no seu CRM.
const token = b['auth[application_token]'] ?? b?.auth?.application_token ?? '';
const esperado = String(cfg.APP_TOKEN || '').trim();
if (esperado && esperado !== 'PREENCHA_APPLICATION_TOKEN' && token !== esperado) {
  throw new Error('application_token nao confere — evento recusado.');
}

// Evento sem ID (ping/handshake do Bitrix): para aqui, sem sujar o log de erro.
if (!activityId) return [];

return [{ json: { activity_id: String(activityId), evento: String(b.event ?? '') } }];

// ONCRMACTIVITYUPDATE dispara em QUALQUER mexida na atividade (editar texto, adiar...).
// ONCRMACTIVITYADD dispara quando o SDR registra uma ligacao JA como concluida.
// Aqui fica so o que interessa: atividade DE NEGOCIO, concluida, feita por gente.
const cfg = $('Config').first().json;
const resp = $input.first().json;

// O no acima segue em frente mesmo com erro (onError). Se o Bitrix RECUSOU, isso
// tem que ficar VERMELHO: sem este throw o unico sintoma e "o negocio nao anda" e
// a execucao aparece verde. O erro classico e insufficient_scope = o webhook de
// ENTRADA foi criado sem a permissao CRM (confira em BASE/scope.json).
if (resp && resp.error) {
  throw new Error('Bitrix recusou o crm.activity.get: ' + resp.error + ' — ' + (resp.error_description || ''));
}

const r = resp.result;
if (!r) return [];

const tipoDono = String(cfg.ENTIDADE).toLowerCase() === 'lead' ? '1' : '2';
if (String(r.OWNER_TYPE_ID) !== tipoDono) return [];   // atividade de contato/empresa: ignora

const concluida =
  String(r.COMPLETED).toUpperCase() === 'Y' ||
  r.COMPLETED === true ||
  String(r.STATUS) === '2';
if (!concluida) return [];

// Filtro opcional por tipo (1=reuniao, 2=ligacao, 3=tarefa, 4=e-mail). Vazio = qualquer um.
const tipos = String(cfg.SO_TIPOS || '').replace(/\s/g, '');
if (tipos && !tipos.split(',').includes(String(r.TYPE_ID))) return [];

// IMPORTANTE: bloqueia atividade criada por robo (canal aberto/WhatsApp, formulario,
// e-mail de marketing). Sem isto uma mensagem automatica move o negocio sozinha.
const bloq = String(cfg.PROVIDERS_IGNORADOS || '').replace(/\s/g, '').split(',').filter(Boolean);
if (bloq.includes(String(r.PROVIDER_ID || ''))) return [];

// Opcional: so conta se o responsavel pela atividade for um dos SDRs listados.
const sdrs = String(cfg.SO_RESPONSAVEIS || '').replace(/\s/g, '').split(',').filter(Boolean);
if (sdrs.length && !sdrs.includes(String(r.RESPONSIBLE_ID || ''))) return [];

return [{ json: {
  activity_id: String(r.ID),
  owner_id: String(r.OWNER_ID),
  assunto: r.SUBJECT || '',
  type_id: String(r.TYPE_ID || ''),
  provider_id: String(r.PROVIDER_ID || ''),
  responsavel: String(r.RESPONSIBLE_ID || '')
} }];

// AQUI mora o "primeira atividade": so move quem AINDA esta em STAGE_DE.
// Concluir a 2a, 3a, 10a atividade nao faz nada, porque o negocio ja saiu de la.
// De quebra, isso impede que o robo puxe pra tras um negocio que ja avancou.
const cfg = $('Config').first().json;
const resp = $input.first().json;

// Mesma regra do no anterior: erro do Bitrix vira execucao VERMELHA, nao silencio.
if (resp && resp.error) {
  throw new Error('Bitrix recusou o crm.' + cfg.ENTIDADE + '.get: ' + resp.error + ' — ' + (resp.error_description || ''));
}

const r = resp.result;
if (!r) return [];

const ehLead = String(cfg.ENTIDADE).toLowerCase() === 'lead';
const campo = ehLead ? 'STATUS_ID' : 'STAGE_ID';
const atual = String(r[campo] || '');

if (atual !== String(cfg.STAGE_DE)) return [];

const fields = {};
fields[campo] = String(cfg.STAGE_PARA);

const atv = $('So atividade concluida do funil').first().json;

return [{ json: {
  id: String(r.ID),
  fields,
  de: atual,
  para: String(cfg.STAGE_PARA),
  assunto: atv.assunto,
  activity_id: atv.activity_id,
  responsavel: atv.responsavel
} }];
